#!/usr/bin/env node
/*
 * pack-repo.js
 * Empaqueta un repositorio en un unico archivo para analisis.
 * Uso: node pack-repo.js <root> <outFile>
 */
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');

const root = path.resolve(process.argv[2] || process.cwd());
const outFile = path.resolve(process.argv[3] || path.join(root, 'repo-bundle.xml'));

// --- Recoleccion de ficheros (usa el indice de git, fallback a walk) ---
let relFiles = [];
try {
    const out = execFileSync('git', ['-C', root, 'ls-files'], { encoding: 'utf8' });
    relFiles = out.split(/\r?\n/).filter(Boolean);
} catch {
    const walk = (dir, acc = []) => {
        for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
            if (e.name === '.git' || e.name === 'node_modules') continue;
            const full = path.join(dir, e.name);
            if (e.isDirectory()) walk(full, acc);
            else acc.push(path.relative(root, full).split(path.sep).join('/'));
        }
        return acc;
    };
    relFiles = walk(root);
}
relFiles.sort();

// --- Lectura y metricas por fichero ---
const files = [];
for (const rel of relFiles) {
    const abs = path.join(root, rel);
    if (!fs.existsSync(abs)) continue;
    const buf = fs.readFileSync(abs);
    const isBinary = buf.includes(0);
    const text = isBinary ? '' : buf.toString('utf8');
    const lines = isBinary ? 0 : (text.length === 0 ? 0 : text.split(/\r?\n/).length);
    files.push({ rel, bytes: buf.length, chars: text.length, lines, isBinary, text });
}

// --- Metricas agregadas ---
const sum = (arr, k) => arr.reduce((a, f) => a + f[k], 0);
const totalBytes = sum(files, 'bytes');
const totalLines = sum(files, 'lines');
const totalChars = sum(files, 'chars');
const totalTokens = Math.ceil(totalChars / 4);

const byDir = new Map();
for (const f of files) {
    const d = path.posix.dirname(f.rel);
    const key = d === '.' ? '(root)' : d;
    if (!byDir.has(key)) byDir.set(key, { files: 0, bytes: 0, lines: 0 });
    const e = byDir.get(key);
    e.files += 1; e.bytes += f.bytes; e.lines += f.lines;
}

// --- Arbol de directorios ---
function buildTree(relFiles) {
    const rootNode = { name: '.', children: new Map(), isFile: false };
    for (const rel of relFiles) {
        const parts = rel.split('/');
        let node = rootNode;
        for (let i = 0; i < parts.length; i++) {
            const last = i === parts.length - 1;
            if (!node.children.has(parts[i])) {
                node.children.set(parts[i], { name: parts[i], children: new Map(), isFile: last });
            }
            node = node.children.get(parts[i]);
        }
    }
    return rootNode;
}
function renderTree(node, prefix = '') {
    const out = [];
    const entries = [...node.children.values()].sort((a, b) => {
        if (a.isFile !== b.isFile) return a.isFile ? 1 : -1;
        return a.name.localeCompare(b.name);
    });
    entries.forEach((child, i) => {
        const last = i === entries.length - 1;
        out.push(prefix + (last ? '`-- ' : '|-- ') + child.name + (child.isFile ? '' : '/'));
        if (!child.isFile) out.push(...renderTree(child, prefix + (last ? '    ' : '|   ')));
    });
    return out;
}
const treeLines = renderTree(buildTree(relFiles.map((f) => f.rel)));

// --- Formateo de tablas ---
const pad = (s, n) => String(s).padEnd(n, ' ');
const padL = (s, n) => String(s).padStart(n, ' ');
const kb = (b) => (b / 1024).toFixed(1) + ' KB';

const metrics = {
    generated_at: new Date().toISOString(),
    root,
    total_files: files.length,
    total_directories: byDir.size,
    total_bytes: totalBytes,
    total_size: kb(totalBytes),
    total_lines: totalLines,
    total_chars: totalChars,
    estimated_tokens: totalTokens,
    avg_file_lines: files.length ? +(totalLines / files.length).toFixed(1) : 0,
    binary_files: files.filter((f) => f.isBinary).length,
    by_directory: [...byDir.entries()]
        .map(([dir, m]) => ({ directory: dir, files: m.files, lines: m.lines, bytes: m.bytes, size: kb(m.bytes) }))
        .sort((a, b) => b.lines - a.lines),
};

// --- Ensamblado del bundle ---
const L = [];
const rule = '='.repeat(78);
L.push(rule);
L.push(' REPOSITORY BUNDLE - single-file snapshot for analysis');
L.push(` root      : ${root}`);
L.push(` generated : ${metrics.generated_at}`);
L.push(` files     : ${metrics.total_files} in ${metrics.total_directories} dirs | ` +
    `${metrics.total_lines} lines | ${metrics.total_size} | ~${metrics.total_tokens} tokens (est.)`);
L.push(rule);
L.push('');
L.push('<file_metrics_summary>');
L.push('| metric | value |');
L.push('| --- | --- |');
L.push(`| total_files | ${metrics.total_files} |`);
L.push(`| total_directories | ${metrics.total_directories} |`);
L.push(`| total_lines | ${metrics.total_lines} |`);
L.push(`| total_bytes | ${metrics.total_bytes} |`);
L.push(`| total_size | ${metrics.total_size} |`);
L.push(`| total_chars | ${metrics.total_chars} |`);
L.push(`| estimated_tokens | ${metrics.estimated_tokens} |`);
L.push(`| avg_lines_per_file | ${metrics.avg_file_lines} |`);
L.push('</file_metrics_summary>');
L.push('');
L.push('<metrics_by_directory>');
L.push('| directory | files | lines | size |');
L.push('| --- | ---: | ---: | ---: |');
for (const d of metrics.by_directory) {
    L.push(`| ${d.directory} | ${d.files} | ${d.lines} | ${d.size} |`);
}
L.push('</metrics_by_directory>');
L.push('');
L.push('<directory_structure>');
L.push(...treeLines);
L.push('</directory_structure>');
L.push('');
L.push('<metrics_by_file>');
L.push('| file | lines | bytes |');
L.push('| --- | ---: | ---: |');
for (const f of files) L.push(`| ${f.rel} | ${f.lines} | ${f.bytes} |`);
L.push('</metrics_by_file>');
L.push('');
L.push('<files>');
for (const f of files) {
    L.push('');
    L.push(`<file path="${f.rel}">`);
    if (f.isBinary) {
        L.push('[binary file - content omitted]');
    } else {
        L.push(f.text.replace(/\r\n/g, '\n').replace(/\n$/, ''));
    }
    L.push('</file>');
}
L.push('');
L.push('</files>');
L.push('');
L.push(rule);
L.push(' END OF BUNDLE');
L.push(rule);

const bundle = L.join('\n');
fs.writeFileSync(outFile, bundle, 'utf8');

// --- Salida por consola: resumen de metricas ---
const w = (s) => process.stdout.write(s + '\n');
w('');
w('=== REPO BUNDLE - METRIC SUMMARY ===');
w(`output_file      : ${outFile}`);
w(`bundle_size      : ${kb(fs.statSync(outFile).size)} (${fs.statSync(outFile).size} bytes)`);
w('');
w(`total_files      : ${metrics.total_files}`);
w(`total_directories: ${metrics.total_directories}`);
w(`total_lines      : ${metrics.total_lines}`);
w(`total_size       : ${metrics.total_size} (${totalBytes} bytes)`);
w(`total_chars      : ${metrics.total_chars}`);
w(`estimated_tokens : ${metrics.estimated_tokens} (~chars/4)`);
w(`avg_lines/file   : ${metrics.avg_file_lines}`);
w('');
w('--- TOP 12 DIRECTORIES BY LINES ---');
metrics.by_directory.slice(0, 12).forEach((d, i) => {
    w(`${padL(i + 1, 2)}. ${pad(d.directory, 28)} ${padL(d.files, 4)} files ${padL(d.lines, 7)} lines ${padL(d.size, 9)}`);
});
w('');
w('--- TOP 10 FILES BY LINES ---');
[...files].sort((a, b) => b.lines - a.lines).slice(0, 10).forEach((f, i) => {
    w(`${padL(i + 1, 2)}. ${pad(f.rel, 46)} ${padL(f.lines, 7)} lines ${padL(f.bytes, 8)} bytes`);
});
w('');
w(`--- EXTENSION BREAKDOWN ---`);
const ext = new Map();
for (const f of files) {
    const e = path.extname(f.rel) || '(none)';
    if (!ext.has(e)) ext.set(e, { files: 0, lines: 0, bytes: 0 });
    const x = ext.get(e); x.files++; x.lines += f.lines; x.bytes += f.bytes;
}
[...ext.entries()].sort((a, b) => b[1].lines - a[1].lines).forEach(([e, x]) => {
    w(`${pad(e, 10)} ${padL(x.files, 4)} files ${padL(x.lines, 7)} lines ${padL(kb(x.bytes), 10)}`);
});
w('');
w('--- JSON METRICS ---');
w(JSON.stringify(metrics, null, 2));
w('');

